            let sectionMeta = null;
            if (typeof entry === 'string') {
                items.push(entry);
            } else if (entry && typeof entry === 'object') {
                sectionMeta = {
                    id: entry.id || null,
                    condition: entry.condition || null
                };
                if (typeof entry.prompt === 'string') {
                    items.push(entry.prompt);
                }
                if (Array.isArray(entry.prompts)) {
